    """
    Resta cantidad al producto. Si queda en 0 o menos, elimina el producto. 
    Si no existe, no hace nada. Devuelve el inventario.
    """
    if nombre in inv:
        if cantidad <= 0:
            return inv  # No hacer nada si la cantidad a quitar es no positiva

        inv[nombre]['cantidad'] -= cantidad

        if inv[nombre]['cantidad'] <= 0:
            del inv[nombre]

    return inv

