def contar_por_nivel(registros):
    """
    Recibe una lista de dicts con claves 'nivel', 'fecha' y 'mensaje'. 
    Devuelve un dict {nivel: cantidad} que incluye SIEMPRE las cuatro claves 
    ERROR, WARN, INFO y DEBUG, con 0 en las que no aparezcan.
    """
    niveles_esperados = ['ERROR', 'WARN', 'INFO', 'DEBUG']
    conteo = {nivel: 0 for nivel in niveles_esperados}

    for registro in registros:
        nivel = registro.get('nivel')
        if nivel in conteo:
            conteo[nivel] += 1

    return conteo

